<?php
declare(strict_types=1);require_once __DIR__.'/includes/init.php';require_role('encargado','docente');
$pageTitle='Mi perfil';$p=db();$uid=(int)current_user()['id'];$q=$p->prepare("SELECT id,nombre,apellido,cedula,email,rol,foto_perfil,ultimo_acceso,creado_en FROM usuarios WHERE id=:id");$q->execute(['id'=>$uid]);$profile=$q->fetch();$turns=active_turns_for_user($uid);
$q=$p->prepare("SELECT h.dia_semana,h.hora_inicio,h.hora_fin,h.asignatura,h.grupo,s.nombre sala,t.nombre turno FROM horarios_docentes h JOIN salas s ON s.id=h.sala_id JOIN turnos t ON t.id=h.turno_id WHERE h.docente_id=:d AND h.anio_lectivo=YEAR(CURDATE()) AND h.activo=1 AND h.eliminado_en IS NULL ORDER BY h.dia_semana,h.hora_inicio LIMIT 10");$q->execute(['d'=>$uid]);$schedule=$q->fetchAll();
$q=$p->prepare("SELECT ss.checkin_en,ss.checkout_en,s.nombre sala FROM sesiones_sala ss JOIN salas s ON s.id=ss.sala_id WHERE ss.docente_id=:d ORDER BY ss.checkin_en DESC LIMIT 6");$q->execute(['d'=>$uid]);$sessions=$q->fetchAll();require __DIR__.'/includes/header.php';
?>
<section class="grid grid-3 profile-grid">
 <article class="card profile-summary"><div class="card-body"><?php if($profile['foto_perfil']):?><img class="profile-photo" src="<?=e(url($profile['foto_perfil']))?>" alt="Foto de perfil"><?php else:?><div class="profile-monogram"><?=e(strtoupper(substr($profile['nombre'],0,1).substr($profile['apellido'],0,1)))?></div><?php endif;?><h2><?=e($profile['nombre'].' '.$profile['apellido'])?></h2><p><?=e(role_label($profile['rol']))?></p><dl class="detail-list"><div><dt>Correo</dt><dd><?=e($profile['email'])?></dd></div><div><dt>Cédula</dt><dd><?=e($profile['cedula']??'-')?></dd></div><div><dt>Turnos</dt><dd><?=e(implode(', ',array_column($turns,'nombre'))?:'-')?></dd></div><div><dt>Último acceso</dt><dd><?=e(format_datetime($profile['ultimo_acceso']))?></dd></div></dl></div></article>
 <article class="card profile-main"><div class="card-header"><h2>Seguridad de la cuenta</h2></div><div class="card-body"><p class="text-muted">Podés actualizar tu contraseña sin intervención del Encargado.</p><form action="<?=e(url('php/perfil_password.php'))?>" method="post"><?=csrf_field()?><div class="form-group"><label>Contraseña actual</label><input name="actual" type="password" required autocomplete="current-password"></div><div class="form-group mt-2"><label>Nueva contraseña</label><input name="nueva" type="password" minlength="8" required autocomplete="new-password"></div><div class="form-group mt-2"><label>Repetir nueva contraseña</label><input name="repetir" type="password" minlength="8" required autocomplete="new-password"></div><div class="form-actions"><button class="btn btn-primary">Actualizar contraseña</button></div></form></div></article>
 <article class="card"><div class="card-header"><h2>Actividad reciente</h2></div><div class="card-body"><?php if(!$sessions):?><p class="text-muted">Sin registros recientes.</p><?php else:?><ul class="activity-list compact"><?php foreach($sessions as $s):?><li><div><strong><?=e($s['sala'])?></strong><span><?=e(format_datetime($s['checkin_en']))?></span></div><small><?=e($s['checkout_en']?'Finalizada':'Sesión abierta')?></small></li><?php endforeach;?></ul><?php endif;?></div></article>
</section>
<?php if(is_docente()):?><section class="card mt-3"><div class="card-header"><h2>Mi horario de esta semana</h2></div><div class="card-body"><?php if(!$schedule):?><div class="empty-state">No hay horarios activos.</div><?php else:?><div class="schedule-week"><?php for($d=1;$d<=5;$d++):?><article class="schedule-day"><h3><?=e(day_name($d))?></h3><?php $found=false;foreach($schedule as $h):if((int)$h['dia_semana']!==$d)continue;$found=true;?><div class="schedule-slot"><strong><?=e(format_time($h['hora_inicio']).' - '.format_time($h['hora_fin']))?></strong><span><?=e($h['sala'].' · '.$h['turno'])?></span><small><?=e($h['asignatura']?:'Clase')?><?=$h['grupo']?' · '.e($h['grupo']):''?></small></div><?php endforeach;if(!$found):?><p class="text-muted">Sin clases.</p><?php endif;?></article><?php endfor;?></div><?php endif;?></div></section><?php endif;?>
<?php require __DIR__.'/includes/footer.php';?>
